import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("plain sword, newcomer → 100 base + 10 first insurance + 5 fee = 115 G");
    it.todo("plain amulet, newcomer → 60 + 6 + 5 = 71 G");
    it.todo("plain staff, newcomer → 80 + 8 + 5 = 93 G");
    it.todo("plain potion, newcomer → 40 + 4 + 5 = 49 G");
  });

  describe("quote — components and blocks", () => {
    it.todo("2 runes → 50 G base premium (55 + 5 = 60 G premium)");
    it.todo("3 runes → 60 G base premium, block applies (66 + 5 = 71 G premium)");
    it.todo("4 runes → 100 G base premium, no block (110 + 5 = 115 G premium)");
    it.todo("7 runes → 175 G base premium (192.5 + 5 → 198 G premium, rounded up)");
    it.todo("2 runes + 1 moonstone → 75 G base premium, different types do not form a block (82.5 + 5 → 88 G)");
    it.todo("3 runes + 3 moonstones → 120 G base premium, two separate blocks (132 + 5 = 137 G)");
  });

  describe("quote — premium modifiers", () => {
    it.todo("newcomer with a cursed sword (steel, enchantment 3) → 165 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge applies (100 + 30 + 10 + 5 = 145 G)");
    it.todo("cursed sword with exactly enchantment 5 → both surcharges apply (100 + 50 + 30 + 10 + 5 = 195 G)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge (115 G)");
    it.todo("customer with exactly 2 years → loyalty discount applies (100 − 20 + 10 + 5 = 95 G)");
    it.todo("customer with 1 year → no loyalty discount (115 G)");
    it.todo("cursed sword + plain amulet → curse surcharge only on the sword's base premium (160 + 50 + 16 + 5 = 231 G)");
    it.todo("policy-wide modifiers apply to the policy base premium, not including item surcharges");
    it.todo("second quote in scenario gets 15 % follow-up discount (sword newcomer: 100 + 10 − 15 + 5 = 100 G)");
    it.todo("long-standing customer's second contract, cursed sword enchantment 7 → 160 G (first insurance still applies)");
    it.todo("rounds fractional premium up in the MHPCO's favor (197.5 → 198 G)");
  });

  describe("claim — payouts", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G, remainingCap 1600 G");
    it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");
    it.todo("steel sword enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword enchantment 5, damage 800 G → payout 700 G");
    it.todo("dragon-material sword enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 G → payout 400 G");
    it.todo("damage below the deductible → payout 0 G");
    it.todo("dragon attack on sword (500 G) and amulet (300 G) → payout 600 G, deductible per damaged item");
    it.todo("two swords insured → cap 4000 G; damage to both swords each has its own deductible");
    it.todo("sword + amulet policy → cap 3200 G");
    it.todo("cursed sword → cap 2000 G (based on unmodified insurance value)");
    it.todo("sword + 3 runes → insurance sum 1750 G, cap 3500 G (block affects premium only)");
    it.todo("two successive 1500 G claims on a sword → 1400 G (cap remaining 600 G), then 600 G (cap remaining 0 G)");
    it.todo("rounds fractional payout down in the MHPCO's favor (350.5 → 350 G)");
  });

  describe("errors", () => {
    it.todo("quote with unknown item type (broomstick) → throws");
    it.todo("claim for an item not covered by the policy (amulet when only sword insured) → throws");
    it.todo("claim for an unknown item type → throws");
    it.todo("claim with more damage entries of a type than the policy covers → throws");
    it.todo("claim with negative damage amount (-200) → throws");
  });

  describe("CLI", () => {
    it.todo("reads the schema example scenario from stdin and writes results JSON to stdout");
    it.todo("exits non-zero with an error on stderr and no results on stdout for an unknown item type");
  });
});

