  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step, index) => {
    const hasPreviousQuote = index > 0;
    return {
      premium: quotePremium(
        step.items,
        scenario.customer.yearsWithMHPCO,
        hasPreviousQuote,
      ),
    };
  }),
});

